_CHANNEL_MACROS = set(CHANNEL_NAMES.values())


HEADER_PREAMBLE = """\
/* Auto-generated by spu_lifter.py -- do not edit by hand. */
#pragma once
#include "../../runtime/spu/spu_context.h"

#ifdef __cplusplus
extern "C" {
#endif

/* Cross-function branch/loop = a guest tail-jump to another lifted function's
 * entry. It MUST reuse the current host frame, not nest one: SPURS task loops
 * iterate via these, so nesting overflows the host stack and silently kills the
 * process. clang's musttail guarantees the tail call (a jump); without it (or on
 * a non-clang compiler) we fall back to call+return, which only stays bounded if
 * the compiler happens to do sibling-call optimization. All lifted SPU functions
 * share the signature `void f(spu_context*)`, so the tail call is always valid. */
#if defined(__clang__)
#  define SPU_TAILCALL(call) __attribute__((musttail)) return call
#else
#  define SPU_TAILCALL(call) do { call; return; } while (0)
#endif

/* Indirect branch dispatch (bi/bisl/bid...): PC has been set to the target
 * local-store address; the runtime resolves it to the matching lifted
 * function and continues execution. */
void spu_indirect_branch(spu_context* ctx);

/* stop/stopd hook (YDKJ): the runtime inspects the stop code, may deliver a
 * stop-and-signal event to the PPU (SPURS bring-up handshake), and longjmps the
 * host SPU thread back to spu_run_with_halt so the job does not spin past the
 * stop. Complements ctx->status; harmless where the runtime handles status. */
void spu_stop(spu_context* ctx);
/* Lower-level longjmp helper: abort the host SPU thread back to spu_run_with_halt
 * (used for the infinite no-op self-loop / idle halt idiom). */
void spu_halt(spu_context* ctx);

/* Channel access -- implemented by the runtime (MFC DMA engine, mailboxes,
 * signal notification, decrementer). See runtime/spu/spu_dma.h. */
u128 spu_rdch(spu_context* ctx, uint32_t channel);
uint32_t spu_rchcnt(spu_context* ctx, uint32_t channel);
void spu_wrch(spu_context* ctx, uint32_t channel, u128 value);

/* Execution trace (only emitted when the lifter was invoked with --trace). */
void spu_trace_init(const char* path);
void spu_trace_pc(spu_context* ctx, uint32_t pc);
void spu_trace_rt(spu_context* ctx, uint32_t rt);

#ifdef __cplusplus
}
#endif
"""

SOURCE_PREAMBLE = """/* Auto-generated by spu_lifter.py -- do not edit by hand. */
#include "{header_name}"
#include "../../runtime/spu/spu_helpers.h"
"""


def _ops(operands: str) -> list[str]:
    return [o.strip() for o in operands.split(",") if o.strip()]


def _reg(token: str) -> str:
    m = re.match(r"\$r(\d+)", token.strip())
    return m.group(1) if m else token.strip()


def _disp_base(token: str):
    m = re.match(r"(-?0x[0-9A-Fa-f]+|-?\d+)\(\$r(\d+)\)", token.strip())
    if m:
        return m.group(1), m.group(2)
    return None, None


def _imm(token: str) -> str:
    token = token.strip()
    if token.startswith("0x") or token.startswith("-0x"):
        return token
    try:
        return str(int(token))
    except ValueError:
        pass
    m = re.match(r"\$r(\d+)$", token)
    if m:
        return m.group(1)
    return "0"


_MFC_LATCH = {c: v for k, v in {(16, "MFC_LSA"): ("mfc_lsa", ""), (17, "MFC_EAH"): ("mfc_eah", ""),
                                (18, "MFC_EAL"): ("mfc_eal", ""), (19, "MFC_Size"): ("mfc_size", ""),
                                (20, "MFC_TagID"): ("mfc_tag", " & 0x1F"),
                                (22, "MFC_WrTagMask"): ("mfc_tag_mask", "")}.items() for c in (str(k[0]), k[1])}


def _chan(token: str) -> str:
    token = token.strip()
    if token in _CHANNEL_MACROS:
        return token
    m = re.match(r"ch(\d+)", token)
    if m:
        return m.group(1)
    return token


@dataclass
class LiftedFunction:
    name: str = ""
    start_addr: int = 0
    end_addr: int = 0
    body_lines: list[str] = field(default_factory=list)
    calls: list[int] = field(default_factory=list)


_COND_BR = {"brz", "brnz", "brhz", "brhnz"}


_NO_RT_WRITE = {
    "stop", "stopd", "lnop", "nop", "sync", "syncc", "dsync",
    "bi", "iret", "biz", "binz", "bihz", "bihnz",
    "br", "bra", "brz", "brnz", "brhz", "brhnz",
    "hbr", "hbra", "hbrr",
    "stqd", "stqa", "stqr", "stqx",
    "wrch",
    "hgt", "hlgt", "heq", "hgti", "hlgti", "heqi",
}


def _bi_target_reg(insn):
    ops = _ops(insn.operands)
    if insn.mnemonic == "bi" and ops:
        return _reg(ops[0])
    if insn.mnemonic in ("biz", "binz", "bihz", "bihnz") and len(ops) >= 2:
        return _reg(ops[1])
    return None


_RRR_DEST_OPS = {"selb", "shufb", "mpya", "fnms", "fma", "fms"}
_CLEAN_FLOAT = {"fa", "fs", "fm", "fma", "fms", "fnms"}
_ZERO_SIGN_SAFE = {"fa", "fs", "fm", "fma", "fms", "fnms", "fcgt", "fceq", "fcmgt", "fcmeq", "cflts", "cfltu"}
_CLEAN_MOVE = {"ori", "ai", "shlqbyi", "rotqbyi"}
_CLOBBER_ALL = {"brsl", "brasl", "bisl", "bisled", "stop", "stopd", "iret"}

def _dest_reg(insn) -> int:
    if insn.mnemonic in _RRR_DEST_OPS:
        return (insn.raw >> 21) & 0x7F
    return insn.raw & 0x7F


def _is_identity_move(insn) -> bool:
    if insn.mnemonic not in ("ai", "ori"):
        return False
    ops = _ops(insn.operands)
    return len(ops) == 3 and ops[0] == ops[1] and ops[2].strip() in ("0", "0x0")


def compute_bi_r0_jumps(insns, bounds) -> set:
    jumps = set()
    ordered = sorted(insns, key=lambda x: x.addr)
    idx_of = {ins.addr: i for i, ins in enumerate(ordered)}

    def _writes_r0(w):
        return w.mnemonic not in _NO_RT_WRITE and _dest_reg(w) == 0

    for (s, e) in bounds:
        fn = [i for i in ordered if s <= i.addr < e]
        for idx, insn in enumerate(fn):
            if _bi_target_reg(insn) != "0":
                continue
            decided = False
            only_identity = False
            for j in range(idx - 1, -1, -1):
                w = fn[j]
                if w.mnemonic in ("bi", "br", "bra", "iret", "stop", "stopd"):
                    break
                if not _writes_r0(w):
                    continue
                if _is_identity_move(w):
                    only_identity = True
                    continue
                if w.mnemonic in ("lqa", "lqr", "il", "ila"):
                    jumps.add(insn.addr)
                decided = True
                break
            if decided or not only_identity:
                continue
            g = idx_of[insn.addr]
            for j in range(g - 1, max(-1, g - 1 - 12), -1):
                w = ordered[j]
                if not _writes_r0(w) or _is_identity_move(w):
                    continue
                if w.mnemonic in ("il", "ila"):
                    jumps.add(insn.addr)
                break
    return jumps


def merge_chunk_groups(insns, bounds, max_insns, entry_points=()) -> dict:
    call_targets = set(entry_points)
    for ins in insns:
        if ins.mnemonic in ("brsl", "brasl"):
            tgt = SPULifter._branch_target(ins)
            if tgt is not None:
                call_targets.add(tgt)
    groups = {}
    ordered = sorted(bounds)
    i = 0
    while i < len(ordered):
        start, end = ordered[i]
        n = (end - start) // 4
        j = i + 1
        while (j < len(ordered) and ordered[j][0] == end
               and ordered[j][0] not in call_targets
               and n + (ordered[j][1] - ordered[j][0]) // 4 <= max_insns):
            end = ordered[j][1]
            n += (ordered[j][1] - ordered[j][0]) // 4
            j += 1
        if j > i + 1:
            groups[start] = end
        i = j
    return groups


def compute_link_returns(insns, bounds) -> set:
    link_regs = set()
    for insn in insns:
        if insn.mnemonic in ("brsl", "brasl", "bisl", "bisled"):
            link_regs.add(insn.raw & 0x7F)
    link_regs.discard(0)
    if not link_regs:
        return set()

    returns = set()
    ordered = sorted(insns, key=lambda x: x.addr)

    preds: dict = {}
    for insn in ordered:
        if insn.mnemonic in ("br", "bra"):
            i16 = (insn.raw >> 7) & 0xFFFF
            if i16 & 0x8000:
                i16 -= 0x10000
            t = (i16 << 2) if insn.mnemonic == "bra" else (insn.addr + (i16 << 2))
            preds.setdefault(t & 0x3FFFF, []).append(insn.addr)
    idx_of_all = {ins.addr: i for i, ins in enumerate(ordered)}
    for (s, e) in bounds:
        fn = [i for i in ordered if s <= i.addr < e]
        for idx, insn in enumerate(fn):
            tr = _bi_target_reg(insn)
            if tr is None or tr == "0":
                continue
            try:
                rn = int(tr)
            except ValueError:
                continue
            if rn not in link_regs:
                continue
            written = False
            block_start = s
            gi = idx_of_all[insn.addr]
            for j in range(gi - 1, -1, -1):
                w = ordered[j]
                if w.mnemonic in ("bi", "br", "bra", "iret", "stop", "stopd"):
                    block_start = ordered[j + 1].addr
                    break
                if (w.mnemonic not in _NO_RT_WRITE and _dest_reg(w) == rn
                        and not _is_identity_move(w)):
                    written = True
                    break
            if written:
                continue
            computed_in = False
            for t, srcs in preds.items():
                if not (block_start <= t <= insn.addr):
                    continue
                for src in srcs:
                    k = idx_of_all.get(src)
                    if k is None:
                        continue
                    for j in range(k - 1, max(-1, k - 24), -1):
                        w = ordered[j]
                        if w.mnemonic in ("bi", "br", "bra", "iret", "stop", "stopd"):
                            break
                        if (w.mnemonic not in _NO_RT_WRITE and _dest_reg(w) == rn
                                and not _is_identity_move(w)):
                            computed_in = True
                            break
                    if computed_in:
                        break
                if computed_in:
                    break
            if not computed_in:
                returns.add(insn.addr)
    return returns


LV2_RESUMING_STOPS = {0x100, 0x110, 0x111}

class SPULifter:
    def __init__(self, trace: bool = False, prefix: str = ""):
        self.functions: list[LiftedFunction] = []
        self.call_targets: set[int] = set()
        self.branch_targets: set[int] = set()
        self.unsupported: dict[str, int] = {}
        self.trace = trace
        if prefix and not prefix.endswith("_"):
            sys.stderr.write(
                f"[spu_lifter] symbol prefix {prefix!r} has no trailing "
                f"underscore; using {prefix + chr(95)!r}"+chr(10))
            prefix += "_"
        self.prefix = prefix
        self.reloc = False
        self.bi_r0_jump: set = set()
        self.link_return: set = set()
        self.promote = True
        self.promote_regs = 2
        self.defer = False
        self._pending: list = []
        self._prom = False
        self._regs: set = set()
        self._jt_targets: list = []
        self._facts: frozenset = frozenset()

    def _g(self, i) -> str:
        s = str(i).strip()
        if not self._prom or not s.isdigit():
            return f"ctx->gpr[{s}]"
        self._regs.add(int(s))
        return f"sr{int(s)}"

    def _jump(self, expr: str, ret: bool = False) -> str:
        if not self._jt_targets:
            return ""
        guard = "!ctx->irq_saved && g_spu_direct > 0 && ctx->steps"
        if ret:
            guard = f"ctx->host_depth == 0 && _jt != ctx->drain_ret_pc && {guard}"
        cases = " ".join(f"case 0x{a:X}u: goto loc_{a:08X};" for a in self._jt_targets)
        pc = "ctx->pc = _jt; " if ret else ""
        return f"{{ const uint32_t _jt = {expr}; if ({guard}) {{ {pc}switch (_jt) {{ {cases} default: break; }} }} }} "

    @staticmethod
    def _spill(regs) -> str:
        return " ".join(f"ctx->gpr[{r}] = sr{r};" for r in sorted(regs))

    def _known_facts(self, fins, entries) -> list:
        n = len(fins)
        idx = {ins.addr: k for k, ins in enumerate(fins)}
        preds = [[] for _ in range(n)]
        succs = [[] for _ in range(n)]
        for k, ins in enumerate(fins):
            for t in ([k + 1] if k + 1 < n and ins.mnemonic not in ("br", "bra", "bi", "iret") else []) + \
                    ([idx[self._branch_target(ins)]] if self._branch_target(ins) in idx else []):
                preds[t].append(k)
                succs[k].append(t)

        def transfer(ins, s):
            mn, o = ins.mnemonic, _ops(ins.operands)
            if mn in _CLOBBER_ALL:
                return frozenset()
            if mn in _NO_RT_WRITE:
                return s
            d = _dest_reg(ins)
            r = [int(x[2:]) if re.fullmatch(r"\$r\d+", x) else int(x, 0) if re.fullmatch(r"-?(0x[0-9A-Fa-f]+|\d+)", x) else None for x in o]
            const = {f[1]: f[2] for f in s if f[0] == "k"}
            new = set()
            if mn in ("il", "ila", "ilh", "ilhu", "iohl"):
                v = {"il": r[1], "ila": r[1], "ilh": (r[1] & 0xFFFF) * 0x10001, "ilhu": (r[1] & 0xFFFF) << 16,
                     "iohl": const.get(d, 0) | (r[1] & 0xFFFF)}[mn] & 0xFFFFFFFF
                if mn != "iohl" or d in const:
                    new.add(("k", d, v))
                if (v >> 23) & 0xFF != 0xFF and (mn != "iohl" or d in const or ("c", d) in s):
                    new.add(("c", d))
            elif mn in _CLEAN_FLOAT or mn in ("csflt", "cuflt"):
                new.add(("c", d))
            elif mn in ("cbd", "chd", "cwd", "cdd", "cbx", "chx", "cwx", "cdx"):
                new.add(("i", d))
            elif mn in ("fcgt", "fceq", "fcmgt", "fcmeq", "ceq", "cgt", "clgt", "ceqi", "cgti", "clgti"):
                new.add(("m", d))
            elif mn in _CLEAN_MOVE and (r[2] == 0 or (mn != "ori" and mn != "ai" and r[2] % 4 == 0)):
                same = r[2] == 0 or (mn == "rotqbyi" and r[2] % 16 == 0)
                new |= {(f[0], d) + f[2:] for f in s if f[1] == r[1] and (same or f[0] in ("c", "m") or (f[0] == "k" and mn == "rotqbyi"))}
            elif mn == "and":
                new |= {("c", d)} if ("c", r[1]) in s or ("c", r[2]) in s else set()
                new |= {("m", d)} if ("m", r[1]) in s and ("m", r[2]) in s else set()
            elif mn == "andc" and ("c", r[1]) in s:
                new.add(("c", d))
            elif mn == "xor" and any(("c", a) in s and not (const.get(b, -1) & 0x7F800000) for a, b in ((r[1], r[2]), (r[2], r[1]))):
                new.add(("c", d))
            elif mn == "selb" and ("c", r[1]) in s and ("c", r[2]) in s and ("m", r[3]) in s:
                new.add(("c", d))
            return frozenset(f for f in s if f[1] != d) | new

        out = [None] * n
        facts = [frozenset()] * n
        work = list(range(n - 1, -1, -1))
        queued = set(work)
        while work:
            k = work.pop()
            queued.discard(k)
            s = frozenset()
            if k and fins[k].addr not in entries and preds[k]:
                known = [out[p] for p in preds[k] if out[p] is not None]
                if not known:
                    continue
                s = frozenset.intersection(*known)
            facts[k] = s
            o = transfer(fins[k], s)
            if o != out[k]:
                out[k] = o
                for j in succs[k]:
                    if j not in queued:
                        queued.add(j)
                        work.append(j)
        return facts

    def _zero_sign_needed(self, fins, entries) -> list:
        n = len(fins)
        if not n:
            return []
        idx = {ins.addr: k for k, ins in enumerate(fins)}
        succs = [[] for _ in range(n)]
        preds = [[] for _ in range(n)]
        exits = [False] * n
        _BARRIER = {"bi", "bisl", "bisled", "biz", "binz", "bihz", "bihnz", "brsl", "brasl", "iret", "stop", "stopd"}
        for k, ins in enumerate(fins):
            mn = ins.mnemonic
            if mn in _BARRIER:
                exits[k] = True
                continue
            if mn in ("br", "bra"):
                t = idx.get(self._branch_target(ins))
                if t is not None:
                    succs[k].append(t); preds[t].append(k)
                else:
                    exits[k] = True
                continue
            if mn in ("brz", "brnz", "brhz", "brhnz"):
                t = idx.get(self._branch_target(ins))
                if t is not None:
                    succs[k].append(t); preds[t].append(k)
                else:
                    exits[k] = True
            if k + 1 < n:
                succs[k].append(k + 1); preds[k + 1].append(k)
            else:
                exits[k] = True

        all_regs = frozenset(range(128))
        reg_re = re.compile(r"\$r(\d+)")
        writes = [None] * n
        reads = [frozenset()] * n
        prop_reads = [frozenset()] * n
        is_barrier = [False] * n
        is_safe = [False] * n
        _PROP_MOVE = {"ori", "ai", "rotqbyi", "shlqbyi"}
        for k, ins in enumerate(fins):
            mn = ins.mnemonic
            if mn in _BARRIER or mn.startswith("wr") or mn.startswith("rd"):
                is_barrier[k] = True
                continue
            o = _ops(ins.operands)
            w = None if (mn in _NO_RT_WRITE or mn == "iohl") else _dest_reg(ins)
            writes[k] = w
            is_safe[k] = mn in _ZERO_SIGN_SAFE
            rs = set()
            for j, tok in enumerate(o):
                if j == 0 and w is not None:
                    continue
                for m in reg_re.finditer(tok):
                    rs.add(int(m.group(1)))
            if mn == "iohl" and o:
                for m in reg_re.finditer(o[0]):
                    rs.add(int(m.group(1)))
            if mn in _PROP_MOVE and len(o) >= 3 and re.fullmatch(r"-?(0x[0-9A-Fa-f]+|\d+)", o[2]) and (
                    int(o[2], 0) == 0 or (mn in ("rotqbyi", "shlqbyi") and int(o[2], 0) % 4 == 0)):
                prop_reads[k] = frozenset(rs)
                reads[k] = frozenset()
            elif mn in ("shufb", "selb") and len(o) >= 4:
                m1, m2, m3 = reg_re.search(o[1]), reg_re.search(o[2]), reg_re.search(o[3])
                if m1 and m2 and m3:
                    prop_reads[k] = frozenset((int(m1.group(1)), int(m2.group(1))))
                    reads[k] = frozenset((int(m3.group(1)),))
                else:
                    reads[k] = frozenset(rs)
            else:
                reads[k] = frozenset(rs)

        need_after = [all_regs if exits[k] else frozenset() for k in range(n)]
        need_before = [frozenset() for _ in range(n)]
        work = list(range(n))
        queued = set(work)
        while work:
            k = work.pop()
            queued.discard(k)
            na = all_regs if exits[k] else frozenset().union(*(need_before[s] for s in succs[k]))
            need_after[k] = na
            if is_barrier[k]:
                nb = all_regs
            else:
                w = writes[k]
                nb = na - ({w} if w is not None else frozenset())
                if not is_safe[k]:
                    nb = nb | reads[k]
                    if prop_reads[k] and (w is None or w in na):
                        nb = nb | prop_reads[k]
            if nb != need_before[k]:
                need_before[k] = nb
                for p in preds[k]:
                    if p not in queued:
                        queued.add(p)
                        work.append(p)
        return need_after

    def _copy_loops(self, fins, labels) -> dict:
        idx = {ins.addr: k for k, ins in enumerate(fins)}
        out = {}
        for k, br in enumerate(fins):
            h = idx.get(self._branch_target(br), k) if br.mnemonic in ("brz", "brnz") else k
            if h < k and not any(fins[j].addr in labels for j in range(h + 1, k + 1)):
                c = self._copy_loop(fins[h:k + 1])
                if c:
                    out[fins[h].addr] = c
        return out

    def _copy_loop(self, body) -> str:
        val, heads, store = {}, set(), None

        def rd(r):
            if r not in val:
                heads.add(r)
                return ("a", r, 0)
            return val[r]

        for ins in body[:-1]:
            mn, o = ins.mnemonic, _ops(ins.operands)
            if mn in ("nop", "lnop", "hbr", "hbra", "hbrr"):
                continue
            regs = [_reg(x) for x in o]
            if mn in ("lqd", "stqd"):
                d, b = _disp_base(o[1])
                if b is None:
                    return ""
                a = rd(b)
                if a[0] != "a":
                    return ""
                a = (a[1], a[2] + int(d, 0))
                if mn == "lqd":
                    val[regs[0]] = ("q",) + a
                    continue
                v = rd(regs[0])
                if store or v[0] != "i" or v[3:] != a:
                    return ""
                store = v
                continue
            arity = {"ai": 1, "cbd": 1, "rotqby": 2, "ceq": 2, "shufb": 3}.get(mn)
            if arity is None:
                return ""
            src = [rd(r) for r in regs[1:1 + arity]]
            if mn == "ai" and src[0][0] == "a":
                v = ("a", src[0][1], src[0][2] + int(o[2], 0))
            elif mn == "cbd" and src[0][0] == "a":
                v = ("m", src[0][1], src[0][2] + int(o[2], 0))
            elif mn == "rotqby" and src[0][0] == "q" and src[1][0] == "a" and src[0][1] == src[1][1] \
                    and (src[1][2] - src[0][2] + 3) % 16 == 0:
                v = ("b",) + src[0][1:]
            elif mn == "shufb" and [s[0] for s in src] == ["b", "q", "m"] and src[1][1:] == src[2][1:]:
                v = ("i",) + src[0][1:] + src[1][1:]
            elif mn == "ceq" and src[0][0] == src[1][0] == "a":
                v = ("e",) + src[0][1:] + src[1][1:]
            else:
                return ""
            val[regs[0]] = v
        cond = rd(_reg(_ops(body[-1].operands)[0]))
        step = {}
        for r in heads:
            v = val.get(r, ("a", r, 0))
            if v[:2] != ("a", r):
                return ""
            step[r] = v[2]
        if store is None or step[store[1]] != 1 or step[store[3]] != 1:
            return ""
        if body[-1].mnemonic == "brnz" and cond[0] == "a":
            terms, delta = [(cond[1], cond[2], 1)], step[cond[1]]
        elif body[-1].mnemonic == "brz" and cond[0] == "e":
            terms, delta = [(cond[1], cond[2], 1), (cond[3], cond[4], -1)], step[cond[1]] - step[cond[3]]
        else:
            return ""
        if delta not in (1, -1):
            return ""
        g = self._g
        e0 = " ".join(f"{'+' if s > 0 else '-'} (spu_pref_word({g(r)}) + 0x{k & 0xFFFFFFFF:X}u)" for r, k, s in terms)
        bump = " ".join(f"{g(r)} = spu_ai({g(r)}, (int32_t)((_cn - 1u) * 0x{d & 0xFFFFFFFF:X}u));"
                        for r, d in sorted(step.items(), key=lambda t: int(t[0])) if d)
        return (f"{{ const uint32_t _cn = 1u {'+' if delta < 0 else '-'} (0u {e0}); "
                f"const uint32_t _cs = (spu_pref_word({g(store[1])}) + 0x{store[2] & 0xFFFFFFFF:X}u) & 0x3FFFFu; "
                f"const uint32_t _cd = (spu_pref_word({g(store[3])}) + 0x{store[4] & 0xFFFFFFFF:X}u) & 0x3FFFFu; "
                f"if (_cn - 2u < 0x3FFFFu && _cs + _cn <= 0x40001u && _cd + _cn <= 0x40001u) {{ "
                f"spu_ls_copy_fwd(_ls, _cd, _cs, _cn - 1u); {bump} }} }} ")

    def _lzf_loops(self, fins, copies) -> dict:
        idx = {ins.addr: k for k, ins in enumerate(fins)}
        out = {}
        for k, ins in enumerate(fins):
            if ins.mnemonic != "brz":
                continue
            lit_addr = self._branch_target(ins)
            if lit_addr is None or lit_addr not in idx:
                continue
            lit_k = idx[lit_addr]
            if lit_k >= k or k - lit_k > 40:
                continue
            # Header block right before brz must test clgti ctrl, 31
            br_reg = _reg(_ops(ins.operands)[0])
            clgti_ins = next((fins[j] for j in range(k - 1, max(lit_k, k - 6) - 1, -1)
                              if fins[j].mnemonic == "clgti" and _reg(_ops(fins[j].operands)[0]) == br_reg
                              and int(_ops(fins[j].operands)[2], 0) == 31), None)
            if clgti_ins is None:
                continue
            ctrl_reg = _reg(_ops(clgti_ins.operands)[1])
            # Find literal exit: clgt r_more, r_end, r_src; brz r_more, exit_addr inside [lit_k, k)
            lit_br_k = None
            exit_addr = None
            src_reg = None
            end_reg = None
            for j in range(lit_k, k):
                if fins[j].mnemonic == "brz":
                    ea = self._branch_target(fins[j])
                    if ea is not None and ea in idx and idx[ea] > k and idx[ea] - k <= 90:
                        mr = _reg(_ops(fins[j].operands)[0])
                        cg = next((fins[m] for m in range(j - 1, max(lit_k, j - 4) - 1, -1)
                                   if fins[m].mnemonic == "clgt" and _reg(_ops(fins[m].operands)[0]) == mr), None)
                        if cg is not None:
                            lit_br_k = j
                            exit_addr = ea
                            end_reg = _reg(_ops(cg.operands)[1])
                            src_reg = _reg(_ops(cg.operands)[2])
                            break
            if lit_br_k is None:
                continue
            hdr_k = lit_br_k + 1
            hdr_addr = fins[hdr_k].addr
            match_k = k + 1
            exit_k = idx[exit_addr]
            if not any(fins[j].addr in copies for j in range(lit_k, lit_br_k)):
                continue
            if not any(fins[j].addr in copies for j in range(match_k, exit_k)):
                continue
            # Find src_cur register in header (ori r_cur, r_src, 0) or preceding ai r_src, r_cur, 1
            src_cur = None
            for j in range(hdr_k, k):
                if fins[j].mnemonic == "ai" and _reg(_ops(fins[j].operands)[0]) == src_reg and int(_ops(fins[j].operands)[2], 0) == 1:
                    src_cur = _reg(_ops(fins[j].operands)[1])
                    break
            if src_cur is None:
                continue
            # Verify match block has rotmi _, ctrl_reg, -5, andi _, ctrl_reg, 31, ceqi _, _, 7, shli _, _, 8, and back-edge brnz hdr_addr
            m_insns = fins[match_k:exit_k]
            if not m_insns or m_insns[-1].mnemonic != "brnz" or self._branch_target(m_insns[-1]) != hdr_addr:
                continue
            has_rotmi = any(i.mnemonic == "rotmi" and _reg(_ops(i.operands)[1]) == ctrl_reg and int(_ops(i.operands)[2], 0) == -5 for i in m_insns)
            has_andi31 = any(i.mnemonic == "andi" and _reg(_ops(i.operands)[1]) == ctrl_reg and int(_ops(i.operands)[2], 0) == 31 for i in m_insns)
            has_ceqi7 = any(i.mnemonic == "ceqi" and int(_ops(i.operands)[2], 0) == 7 for i in m_insns)
            has_shli8 = any(i.mnemonic == "shli" and int(_ops(i.operands)[2], 0) == 8 for i in m_insns)
            if not (has_rotmi and has_andi31 and has_ceqi7 and has_shli8):
                continue
            # Find dst_reg from cbd _, dst_reg, 0 in literal copy loop
            dst_reg = None
            for j in range(lit_k, lit_br_k):
                if fins[j].mnemonic == "cbd":
                    ops_cbd = _ops(fins[j].operands)
                    if len(ops_cbd) >= 2:
                        dst_reg = _reg(ops_cbd[1])
                        break
            if dst_reg is None:
                continue
            g = self._g
            snip = (f"if (!ctx->int_enable) {{ uint32_t _ls_s = spu_pref_word({g(src_cur)}), "
                    f"_ls_d = spu_pref_word({g(dst_reg)}); "
                    f"spu_ls_lzf_decompress(_ls, &_ls_s, spu_pref_word({g(end_reg)}), &_ls_d); "
                    f"{g(src_reg)} = spu_pref_u32(_ls_s); {g(dst_reg)} = spu_pref_u32(_ls_d); "
                    f"goto loc_{exit_addr:08X}; }} ")
            out[lit_addr] = snip
            out[fins[match_k].addr] = snip
        return out

    def lift_function(self, insns: list[SPUInstruction],
                      start: int, end: int) -> LiftedFunction:
        func = LiftedFunction(name=f"{self.prefix}spu_func_{start:08X}",
                              start_addr=start, end_addr=end)

        internal: set[int] = set()
        for insn in insns:
            if insn.addr < start or insn.addr >= end:
                continue
            tgt = self._branch_target(insn)
            if tgt is not None and start <= tgt < end:
                internal.add(tgt)

        merged_starts = {a for a in getattr(self, "func_starts", ()) if start < a < end}
        self._prom = self.promote and not self.trace
        self._regs = set()
        fins = [i for i in insns if start <= i.addr < end]
        self._jt_targets = [] if self.reloc else sorted(merged_starts & {i.addr for i in fins})
        texts = []
        last_insn = None
        copies = {} if self.trace else self._copy_loops(fins, internal | merged_starts)
        if not self.trace and copies:
            for _la, _ls in self._lzf_loops(fins, copies).items():
                copies[_la] = _ls + copies.get(_la, "")
        facts = self._known_facts(fins, merged_starts)
        zs_need = self._zero_sign_needed(fins, merged_starts)
        for k, insn in enumerate(fins):
            self._facts = facts[k]
            self._zs_need = zs_need[k]
            if insn.addr in internal or insn.addr in merged_starts:
                func.body_lines.append(f"loc_{insn.addr:08X}:")
            if insn.addr in merged_starts:
                func.body_lines.append(
                    f"    if (ctx->int_enable && (ctx->event_status & ctx->event_mask)) "
                    f"{{ ctx->pc = {self._pc(insn.addr)}; @I{k}@ g_spu_trampoline_fn = "
                    f"{self.prefix}spu_func_{insn.addr:08X}; return; }}")
            c = copies.get(insn.addr, "") + (self._translate(insn, func) or "")
            c = c.replace("@SPILL@", f"@S{k}@").replace("@RELOAD@", f"@R{k}@")
            texts.append(c)
            if c:
                if self.trace:
                    func.body_lines.append(f"    spu_trace_pc(ctx, {self._pc(insn.addr)});")
                func.body_lines.append(f"    {c}")
                if self.trace and insn.mnemonic not in _NO_RT_WRITE:
                    rt_idx = insn.raw & 0x7F
                    func.body_lines.append(f"    spu_trace_rt(ctx, {rt_idx});")
            last_insn = insn

        _TERMINATORS = {"br", "bra", "bi", "iret", "stop", "stopd"}
        last_k = len(fins) - 1
        if (last_insn is not None
                and (last_insn.mnemonic not in _TERMINATORS
                     or (last_insn.mnemonic == "stop"
                         and (last_insn.raw & 0x3FFF) in LV2_RESUMING_STOPS))):
            if end in getattr(self, "func_starts", set()):
                func.body_lines.append(
                    f"    {{ @O{last_k}@ SPU_DIRECT(ctx, {self._pc(end)}, {self.prefix}spu_func_{end:08X}); }}")
            else:
                func.body_lines.append(f"    @O{last_k}@")
        if any("(_ls, " in t for t in texts):
            func.body_lines.insert(0, "    uint8_t* const _ls = ctx->ls;")

        body_insns = [i for i in insns if start <= i.addr < end]
        if body_insns and all(i.mnemonic in ("nop", "lnop", "br", "bra")
                              for i in body_insns) \
                and body_insns[-1].mnemonic in ("br", "bra") \
                and self._branch_target(body_insns[-1]) is not None \
                and start <= self._branch_target(body_insns[-1]) < end:
            func.body_lines = [
                "    /* infinite no-op self-loop (SPU halt idiom) -> abort */",
                "    spu_halt(ctx); return;",
            ]
        elif self.defer:
            self._pending.append((func, fins, texts, start, end, self._regs, self._prom))
        else:
            self._finish_promotion(func, fins, texts, start, end, self._regs, self._prom, {})

        self.functions.append(func)
        return func

    _CALL_SAFE = {"spu_ls_ld128", "spu_ls_st128", "spu_call_return", "SPU_RET", "SPU_RET_REG", "SPU_DIRECT"}
    _CALL_ANY = ("spu_unsupported", "spu_halt", "SPU_ICALL")

    def finalize(self) -> None:
        pend, self._pending = self._pending, []
        every = (1 << 128) - 1
        fname = re.compile(re.escape(self.prefix) + r"spu_func_([0-9A-F]{8})\b")
        ref = re.compile(r"\bsr(\d+)\b|ctx->gpr\[(\d+)\]")
        ctxcall = re.compile(r"\b(\w+)\s*\(\s*ctx\b")
        own: dict = {}
        for func, fins, texts, start, end, regs, prom in pend:
            mask, deps, wild = 0, set(), False
            for b in func.body_lines:
                for m in ref.finditer(b):
                    mask |= 1 << int(m.group(1) or m.group(2))
                deps.update(int(a, 16) for a in fname.findall(b))
                if any(t in b for t in self._CALL_ANY):
                    wild = True
                for name in ctxcall.findall(b):
                    if name not in self._CALL_SAFE and not fname.fullmatch(name):
                        wild = True
            for ins in fins:
                if ins.mnemonic not in _NO_RT_WRITE:
                    mask |= 1 << _dest_reg(ins)
            own[start] = (every if wild else mask, deps)
        w = {s: m for s, (m, _) in own.items()}
        changed = True
        while changed:
            changed = False
            for s, (m, deps) in own.items():
                v = w[s]
                if v == every:
                    continue
                for d in deps:
                    v |= w.get(d, every)
                    if v == every:
                        break
                if v != w[s]:
                    w[s] = v
                    changed = True
        for func, fins, texts, start, end, regs, prom in pend:
            self._finish_promotion(func, fins, texts, start, end, regs, prom, w)

    def _finish_promotion(self, func: LiftedFunction, fins, texts, start: int, end: int,
                          regs: set, prom: bool, wsum: dict) -> None:
        tok = re.compile(r"@([SIOR])(\d+)@")
        if not prom or not regs:
            func.body_lines = [tok.sub("", b) for b in func.body_lines]
            return
        if len(regs) > self.promote_regs:
            ref = re.compile(r"\bsr(\d+)\b")
            counts: dict = {}
            for t in texts:
                for r in ref.findall(t):
                    counts[int(r)] = counts.get(int(r), 0) + 1
            regs = set(sorted(regs, key=lambda r: (-counts.get(r, 0), r))[:self.promote_regs])

            def demote(s):
                return ref.sub(lambda m: m.group(0) if int(m.group(1)) in regs else f"ctx->gpr[{m.group(1)}]", s)

            texts = [demote(t) for t in texts]
            func.body_lines = [demote(b) for b in func.body_lines]
        n = len(fins)
        idx_of = {ins.addr: k for k, ins in enumerate(fins)}
        assign = re.compile(r"\bsr(\d+) = (?!=)")
        case = re.compile(r"case 0x([0-9A-F]+)u: goto")
        write = []
        for k, ins in enumerate(fins):
            w = {int(r) for r in assign.findall(texts[k])}
            if ins.mnemonic not in _NO_RT_WRITE:
                w.add(_dest_reg(ins))
            write.append({r for r in w if r in regs})
        succ = []
        for k, ins in enumerate(fins):
            mn = ins.mnemonic
            tgt = self._branch_target(ins)
            stop_ends = mn == "stop" and (ins.raw & 0x3FFF) not in LV2_RESUMING_STOPS
            ends = mn in ("br", "bra", "bi", "iret", "stopd") or stop_ends or \
                (mn in ("brsl", "brasl") and tgt == ins.addr)
            s = []
            if not ends and k + 1 < n:
                s.append(k + 1)
            if tgt is not None and start <= tgt < end and tgt in idx_of and \
                    (mn in ("br", "bra") or mn in _COND_BR or (mn in ("brsl", "brasl") and tgt == ins.addr + 4)):
                s.append(idx_of[tgt])
            s.extend(idx_of[int(a, 16)] for a in case.findall(texts[k]) if int(a, 16) in idx_of)
            succ.append(s)
        self._locals(func, fins, texts, succ, regs)
        d_in = [0] * n
        d_out = [None] * n
        mask = [sum(1 << r for r in write[k]) for k in range(n)]

        def transfer(k, d):
            t = texts[k]
            if f"@R{k}@" in t:
                return 0
            mn = fins[k].mnemonic
            if mn in ("rdch", "rchcnt", "wrch") and f"@S{k}@" in t:
                return mask[k]
            return d | mask[k]

        work = list(range(n))
        queued = set(work)
        while work:
            k = work.pop()
            queued.discard(k)
            out = transfer(k, d_in[k])
            if out == d_out[k]:
                continue
            d_out[k] = out
            for s in succ[k]:
                merged = d_in[s] | out
                if merged != d_in[s] or d_out[s] is None:
                    d_in[s] = merged
                    if s not in queued:
                        queued.add(s)
                        work.append(s)

        def bits(v):
            return [r for r in range(128) if v >> r & 1]

        full = sum(1 << r for r in regs)

        def reload(v):
            return " ".join(f"sr{r} = ctx->gpr[{r}];" for r in sorted(regs) if v >> r & 1)

        reload_all = reload(full)

        def sub(m):
            k = int(m.group(2))
            kind = m.group(1)
            if kind == "R":
                if "_fast" not in texts[k]:
                    return reload_all
                wv = wsum.get(self._branch_target(fins[k]), full) & full
                if wv == full:
                    return f"(void)_fast; {reload_all}"
                return f"if (_fast) {{ {reload(wv)} }} else {{ {reload_all} }}"
            if kind == "S" and fins[k].mnemonic in ("rdch", "rchcnt"):
                kind = "I"
            v = d_in[k] | mask[k] if kind == "S" else d_in[k] if kind == "I" else (d_out[k] or 0)
            return self._spill(bits(v))

        func.body_lines = [tok.sub(sub, b) for b in func.body_lines]
        func.body_lines.insert(0, "    u128 " + ", ".join(f"sr{r} = ctx->gpr[{r}]" for r in sorted(regs)) + ";")

    def _locals(self, func: LiftedFunction, fins, texts, succ, regs) -> None:
        n = len(fins)
        every = (1 << 128) - 1
        ref = re.compile(r"ctx->gpr\[(\d+)\]|\bsr(\d+)\b")
        starts = set(getattr(self, "func_starts", ()))
        use, kill, wall = [], [], []
        for k, ins in enumerate(fins):
            cnt: dict = {}
            for a, b in ref.findall(texts[k]):
                cnt[int(a or b)] = cnt.get(int(a or b), 0) + 1
            d = _dest_reg(ins)
            own = ins.mnemonic not in _NO_RT_WRITE and re.match(rf"(ctx->gpr\[{d}\]|sr{d}) = (?!=)",
                                                                 texts[k].rpartition("} ")[2])
            if own:
                cnt[d] -= 1
            use.append(sum(1 << r for r, v in cnt.items() if v > 0))
            kill.append(1 << d if own else 0)
            wall.append(bool(re.search(r"@|\bctx\b(?!->gpr\[|->reloc_delta\b)", texts[k]))
                        or ins.mnemonic in ("rdch", "rchcnt", "wrch") or bool(k) and ins.addr in starts)
        succ = succ + [[]]
        if f"@O{n - 1}@" in func.body_lines[-1]:
            succ[n - 1] = succ[n - 1] + [n]
        use.append(0)
        kill.append(0)
        wall.append(True)
        live = [every if wall[k] else 0 for k in range(n + 1)]
        changed = True
        while changed:
            changed = False
            for k in range(n - 1, -1, -1):
                o = every if not succ[k] else 0
                for s in succ[k]:
                    o |= live[s]
                v = every if wall[k] else use[k] | (o & ~kill[k])
                if v != live[k]:
                    live[k], changed = v, True
        defs: dict = {}
        for k in range(n):
            d = kill[k].bit_length() - 1
            if d >= 0 and not wall[k] and d not in regs:
                defs.setdefault(d, []).append(k)
        resident = [0] + [s for k in range(n) if wall[k] for s in succ[k] if s < n]
        new = list(texts)
        names = set()
        for d, ks in defs.items():
            g, t = f"ctx->gpr[{d}]", f"tr{d}"
            up = {-1: -1}

            def find(x):
                while up[x] != x:
                    up[x] = up[up[x]]
                    x = up[x]
                return x

            owner: dict = {}
            for k in [-1] + ks:
                up[k] = k
                stack = list(resident if k < 0 else succ[k])
                if not stack:
                    up[k] = -1
                seen = set()
                while stack:
                    j = stack.pop()
                    if j in seen or not live[j] >> d & 1:
                        continue
                    seen.add(j)
                    if wall[j] or not succ[j] and not kill[j] >> d & 1:
                        up[find(k)] = find(-1)
                        continue
                    if use[j] >> d & 1:
                        up[find(k)] = find(owner.setdefault(j, k))
                    if not kill[j] >> d & 1:
                        stack.extend(succ[j])
            bad = find(-1)
            lhs = {k for k in ks if find(k) != bad}
            if not lhs:
                continue
            names.add(d)
            for j in lhs | {j for j, k in owner.items() if find(k) != bad}:
                head, sep, tail = new[j].rpartition("} ")
                if find(owner.get(j, -1)) != bad:
                    head = head.replace(g, t)
                    tail = tail[:len(g)] + tail[len(g):].replace(g, t) if kill[j] >> d & 1 else tail.replace(g, t)
                if j in lhs:
                    tail = t + tail[len(g):]
                new[j] = head + sep + tail
        if not names:
            return
        i = 0
        for k in range(n):
            if texts[k]:
                while func.body_lines[i] != f"    {texts[k]}":
                    i += 1
                func.body_lines[i] = f"    {new[k]}"
        func.body_lines.insert(0, "    u128 " + ", ".join(f"tr{r}" for r in sorted(names)) + ";")

    def _pc(self, a: int) -> str:
        if self.reloc:
            return f"((0x{a:X}u + (uint32_t)ctx->reloc_delta) & 0x3FFFFu)"
        return f"0x{a:X}"

    @staticmethod
    def _branch_target(insn: SPUInstruction):
        mn = insn.mnemonic
        ops = _ops(insn.operands)
        if mn not in ("br", "brsl", "bra", "brasl") and mn not in _COND_BR:
            return None
        tok = ops[-1] if ops else None
        if tok and tok.startswith("0x"):
            try:
                return int(tok, 16)
            except ValueError:
                return None
        return None

    def _translate(self, insn: SPUInstruction, func: LiftedFunction) -> str:
        mn = insn.mnemonic
        ops = _ops(insn.operands)
        addr = insn.addr

        def rt(): return _reg(ops[0])
        def ra(): return _reg(ops[1])
        def rb(): return _reg(ops[2])
        g = self._g

        if mn in ("nop", "lnop"):
            return "/* nop */;"
        if mn in ("sync", "dsync", "syncc"):
            return "spu_arch_fence();"
        if mn == "fscrwr":
            return "/* fscrwr: FP status/control write (no-op in recomp) */;"
        if mn == "stop":
            code = insn.raw & 0x3FFF
            if code in LV2_RESUMING_STOPS:
                return (f"ctx->stop_code = 0x{code:X}u; "
                        f"ctx->status = SPU_STATUS_STOPPED_BY_STOP; @SPILL@ spu_stop(ctx); "
                        f"if (ctx->status != SPU_STATUS_RUNNING) return; @RELOAD@")
            return (f"ctx->stop_code = 0x{code:X}u; "
                    f"ctx->status = SPU_STATUS_STOPPED_BY_STOP; @SPILL@ spu_stop(ctx); return;")

        if mn == "il":
            return f"{g(rt())} = spu_il({_imm(ops[1])});"
        if mn == "ila":
            return f"{g(rt())} = spu_ila({_imm(ops[1])});"
        if mn == "ilh":
            return f"{g(rt())} = spu_ilh({_imm(ops[1])});"
        if mn == "ilhu":
            return f"{g(rt())} = spu_ilhu({_imm(ops[1])});"
        if mn == "iohl":
            return f"{g(rt())} = spu_iohl({g(rt())}, {_imm(ops[1])});"
        if mn == "fsmbi":
            return f"{g(rt())} = spu_fsmbi({_imm(ops[1])});"

        if mn == "addx":
            return f"{g(rt())} = spu_addx({g(ra())}, {g(rb())}, {g(rt())});"
        if mn == "bgx":
            return f"{g(rt())} = spu_bgx({g(ra())}, {g(rb())}, {g(rt())});"

        if mn in ("hgti", "hlgti", "heqi", "hgt", "hlgt", "heq"):
            pw = lambda i: f"spu_pref_word({g(i)})"
            if mn == "heqi":
                cond = f"(int32_t){pw(ra())} == (int32_t)({_imm(ops[2])})"
            elif mn == "hgti":
                cond = f"(int32_t){pw(ra())} > (int32_t)({_imm(ops[2])})"
            elif mn == "hlgti":
                cond = f"{pw(ra())} > (uint32_t)({_imm(ops[2])})"
            elif mn == "heq":
                cond = f"{pw(ra())} == {pw(rb())}"
            elif mn == "hgt":
                cond = f"(int32_t){pw(ra())} > (int32_t){pw(rb())}"
            else:
                cond = f"{pw(ra())} > {pw(rb())}"
            return (f"if ({cond}) {{ extern void spu_halt(spu_context*); "
                    f"fprintf(stderr, \"[spu] HALT-ASSERT {mn} pc=0x{addr:05X} "
                    f"img=%d\\n\", ctx->image_id); "
                    f"ctx->status = SPU_STATUS_STOPPED_BY_HALT; "
                    f"@SPILL@ spu_halt(ctx); return; }}")
        if mn == "stopd":
            return ("ctx->stop_code = 0x3FFFu; "
                    "ctx->status = SPU_STATUS_STOPPED_BY_STOP; @SPILL@ spu_stop(ctx); return;")

        rr_bin = {
            "a": "spu_a", "sf": "spu_sf", "ah": "spu_ah", "sfh": "spu_sfh",
            "and": "spu_and", "or": "spu_or", "xor": "spu_xor",
            "nand": "spu_nand", "nor": "spu_nor", "andc": "spu_andc", "orc": "spu_orc",
            "ceq": "spu_ceq", "ceqh": "spu_ceqh", "ceqb": "spu_ceqb",
            "cgt": "spu_cgt", "cgth": "spu_cgth", "cgtb": "spu_cgtb",
            "clgt": "spu_clgt", "clgth": "spu_clgth", "clgtb": "spu_clgtb",
            "mpy": "spu_mpy", "mpyu": "spu_mpyu",
            "mpyh": "spu_mpyh", "mpyhh": "spu_mpyhh", "mpys": "spu_mpys",
            "fi": "spu_fi",
            "fceq": "spu_fceq", "fcgt": "spu_fcgt",
            "fcmeq": "spu_fcmeq", "fcmgt": "spu_fcmgt",
            "dfa": "spu_dfa", "dfs": "spu_dfs", "dfm": "spu_dfm",
            "dfceq": "spu_dfceq", "dfcmeq": "spu_dfcmeq",
            "dfcgt": "spu_dfcgt", "dfcmgt": "spu_dfcmgt",
            "mpyhhu": "spu_mpyhhu",
            "eqv": "spu_eqv", "absdb": "spu_absdb", "avgb": "spu_avgb",
            "cg": "spu_cg", "bg": "spu_bg",
            "sumb": "spu_sumb",
            "dfa": "spu_dfa", "dfs": "spu_dfs", "dfm": "spu_dfm",
            "shl": "spu_shl", "shlh": "spu_shlh",
            "rot": "spu_rot", "roth": "spu_roth",
            "shlqbi": "spu_shlqbi",  "rotqbi": "spu_rotqbi",
            "shlqby": "spu_shlqby",  "rotqby": "spu_rotqby",
            "shlqbybi": "spu_shlqbybi", "rotqbybi": "spu_rotqbybi",
            "rotm": "spu_rotm", "rotma": "spu_rotma",
            "rothm": "spu_rothm", "rotmah": "spu_rothma",
            "rotqmbi": "spu_rotqmbi", "rotqmby": "spu_rotqmby",
            "rotqmbybi": "spu_rotqmbybi",
            "cbx": "spu_cbx", "chx": "spu_chx",
            "cwx": "spu_cwx", "cdx": "spu_cdx",
        }
        if mn in _CLEAN_FLOAT:
            srcs = [ra(), rb()] + ([_reg(ops[3])] if len(ops) > 3 else [])
            k = sum(1 << i for i, r in enumerate(srcs) if ("c", int(r)) in self._facts)
            if int(rt()) not in self._zs_need:
                k |= 8
            args = ", ".join(g(r) for r in srcs)
            return f"{g(rt())} = spu_{mn}_k({args}, {k});" if k else f"{g(rt())} = spu_{mn}({args});"
        if mn in rr_bin:
            return f"{g(rt())} = {rr_bin[mn]}({g(ra())}, {g(rb())});"

        rr_un = {
            "clz": "spu_clz", "cntb": "spu_cntb",
            "fscrrd": "spu_fscrrd",
            "gb": "spu_gb", "gbh": "spu_gbh", "gbb": "spu_gbb",
            "fesd": "spu_fesd", "frds": "spu_frds",
            "frsqest": "spu_frsqest", "frest": "spu_frest",
            "fesd": "spu_fesd", "frds": "spu_frds",
            "xsbh": "spu_xsbh", "xshw": "spu_xshw", "xswd": "spu_xswd",
            "orx": "spu_orx",
            "fsm": "spu_fsm", "fsmh": "spu_fsmh", "fsmb": "spu_fsmb",
            "mfspr": "spu_mfspr",
        }
        if mn in rr_un:
            return f"{g(rt())} = {rr_un[mn]}({g(ra())});"


        ri_imm = {
            "ai": "spu_ai", "ahi": "spu_ahi", "sfi": "spu_sfi", "sfhi": "spu_sfhi",
            "andi": "spu_andi", "ori": "spu_ori", "xori": "spu_xori",
            "ceqi": "spu_ceqi", "cgti": "spu_cgti", "clgti": "spu_clgti",
            "ceqbi": "spu_ceqbi", "ceqhi": "spu_ceqhi",
            "clgtbi": "spu_clgtbi", "clgthi": "spu_clgthi",
            "cgthi": "spu_cgthi", "cgtbi": "spu_cgtbi",
            "mpyi": "spu_mpyi", "mpyui": "spu_mpyui",
            "andhi": "spu_andhi", "andbi": "spu_andbi",
            "orhi":  "spu_orhi",  "orbi":  "spu_orbi",
            "xorhi": "spu_xorhi", "xorbi": "spu_xorbi",
            "dftsv": "spu_dftsv",
            "cflts": "spu_cflts", "cfltu": "spu_cfltu",
            "csflt": "spu_csflt", "cuflt": "spu_cuflt",
        }
        if mn in ri_imm:
            return f"{g(rt())} = {ri_imm[mn]}({g(ra())}, {_imm(ops[2])});"

        sh_imm = {
            "shli": "spu_shli", "shlhi": "spu_shlhi",
            "roti": "spu_roti", "rothi": "spu_rothi",
            "rotmi": "spu_rotmi", "rotmai": "spu_rotmai", "rotmhi": "spu_rotmhi",
            "rotmahi": "spu_rotmahi",
            "shlqbyi": "spu_shlqbyi", "rotqbyi": "spu_rotqbyi",
            "shlqbii": "spu_shlqbii", "rotqbii": "spu_rotqbii",
            "rothmi": "spu_rothmi",
            "rotqmbii": "spu_rotqmbii", "rotqmbyi": "spu_rotqmbyi",
            "cbd": "spu_cbd", "chd": "spu_chd",
            "cwd": "spu_cwd", "cdd": "spu_cdd",
        }
        if mn in sh_imm:
            tok = ops[2]
            if tok.startswith("$r"):
                tok = tok[2:]
            else:
                tok = _imm(tok)
            return f"{g(rt())} = {sh_imm[mn]}({g(ra())}, {tok});"

        if mn == "selb":
            rc = _reg(ops[3])
            return f"{g(rt())} = spu_selb({g(ra())}, {g(rb())}, {g(rc)});"
        if mn == "shufb":
            rc = _reg(ops[3])
            return f"{g(rt())} = spu_shufb{'_ins' if ('i', int(rc)) in self._facts else ''}({g(ra())}, {g(rb())}, {g(rc)});"
        if mn == "mpya":
            rc = _reg(ops[3])
            return f"{g(rt())} = spu_mpya({g(ra())}, {g(rb())}, {g(rc)});"
        if mn == "sfx":
            return f"{g(rt())} = spu_sfx({g(ra())}, {g(rb())}, {g(rt())});"
        if mn == "cgx":
            return f"{g(rt())} = spu_cgx({g(ra())}, {g(rb())}, {g(rt())});"
        if mn in ("dfma", "dfms", "dfnms", "dfnma"):
            return f"{g(rt())} = spu_{mn}({g(ra())}, {g(rb())}, {g(rt())});"
        if mn in ("mpyhha", "mpyhhau"):
            return f"{g(rt())} = spu_{mn}({g(ra())}, {g(rb())}, {g(rt())});"

        if mn == "lqd":
            disp, base = _disp_base(ops[1])
            if disp is not None:
                return f"{g(rt())} = spu_ls_ld128(_ls, spu_pref_word({g(base)}) + {disp});"
        if mn == "stqd":
            disp, base = _disp_base(ops[1])
            if disp is not None:
                return f"spu_ls_st128(_ls, spu_pref_word({g(base)}) + {disp}, {g(rt())});"
        if mn in ("lqa", "lqr"):
            a = self._pc(int(_imm(ops[1]), 0)) if mn == "lqr" and self.reloc else _imm(ops[1])
            return f"{g(rt())} = spu_ls_ld128(_ls, {a});"
        if mn in ("stqa", "stqr"):
            a = self._pc(int(_imm(ops[1]), 0)) if mn == "stqr" and self.reloc else _imm(ops[1])
            return f"spu_ls_st128(_ls, {a}, {g(rt())});"
        if mn == "lqx":
            return f"{g(rt())} = spu_ls_ld128(_ls, spu_pref_word({g(ra())}) + spu_pref_word({g(rb())}));"
        if mn == "stqx":
            return f"spu_ls_st128(_ls, spu_pref_word({g(ra())}) + spu_pref_word({g(rb())}), {g(rt())});"

        if mn == "rdch":
            ch = _chan(ops[1])
            if ch in ("24", "MFC_RdTagStat"):
                return f"{g(rt())} = spu_pref_u32(ctx->mfc_tag_status);"
            if ch in ("27", "MFC_RdAtomicStat"):
                return f"{g(rt())} = spu_pref_u32(ctx->atomic_stat);"
            return f"@SPILL@ {g(rt())} = spu_rdch(ctx, {ch});"
        if mn == "rchcnt":
            ch = _chan(ops[1])
            if ch in ("24", "MFC_RdTagStat"):
                return f"{g(rt())} = spu_pref_u32(1u);"
            return f"@SPILL@ {g(rt())} = spu_pref_u32(spu_rchcnt(ctx, {ch}));"
        if mn == "wrch":
            ch = _chan(ops[0])
            latch = _MFC_LATCH.get(ch)
            if latch:
                return f"ctx->{latch[0]} = spu_pref_word({g(_reg(ops[1]))}){latch[1]};"
            return f"@SPILL@ spu_wrch(ctx, {ch}, {g(_reg(ops[1]))});"

        if mn in ("br", "bra"):
            tgt = self._branch_target(insn)
            if tgt == addr:
                return "ctx->status = SPU_STATUS_STOPPED_BY_HALT; @SPILL@ return;"
            return self._uncond_branch(tgt, func)
        if mn in ("brsl", "brasl"):
            link_rt = insn.raw & 0x7F
            tgt = self._branch_target(insn)
            link = f"{g(link_rt)} = spu_link({self._pc((addr + 4) & 0x3FFFC)});"
            if tgt == addr:
                return f"{link} ctx->status = SPU_STATUS_STOPPED_BY_HALT; @SPILL@ return;"
            if tgt == addr + 4:
                return f"{link} {self._uncond_branch(addr + 4, func)}"
            if tgt is not None:
                self.call_targets.add(tgt)
                rs, rr = ("const int32_t _rd = ctx->reloc_delta; ", " ctx->reloc_delta = _rd;") if self.reloc else ("", "")
                return (f"{link} {{ int32_t _si = (int32_t)ctx->image_id; {rs}"
                        f"@SPILL@ ctx->host_depth++; {self.prefix}spu_func_{tgt:08X}(ctx); "
                        f"const int _fast = spu_call_return(ctx, {self._pc(addr + 4)}); ctx->host_depth--; ctx->image_id = _si;{rr} @RELOAD@ }}")
            return f"{link} /* TODO spu: brsl unresolved target */;"
        if mn in _COND_BR:
            tgt = self._branch_target(insn)
            cond = self._cond(mn, _reg(ops[0]))
            if tgt is None:
                return (f'/* TODO spu: {mn} {insn.operands} */ '
                        f'@SPILL@ spu_unsupported(0x{insn.addr:X}, "{mn}"); @RELOAD@')
            if func.start_addr <= tgt < func.end_addr:
                return f"if ({cond}) goto loc_{tgt:08X};"
            self.branch_targets.add(tgt)
            return (f"if ({cond}) {{ @SPILL@ SPU_DIRECT(ctx, {self._pc(tgt)}, "
                    f"{self.prefix}spu_func_{tgt:08X}); }}")
        _ied = ("ctx->int_enable = 1; " if insn.raw & 0x40000 else
                "ctx->int_enable = 0; " if insn.raw & 0x80000 else "")
        if mn in ("bi",):
            tgt_reg = _reg(ops[0])
            if (tgt_reg == "0" and addr not in self.bi_r0_jump) \
                    or addr in self.link_return:
                jr = self._jump(f"spu_pref_word({g(tgt_reg)})", True)
                if tgt_reg != "0":
                    return f"{_ied}{jr}@SPILL@ SPU_RET_REG(ctx, {tgt_reg});"
                return f"{_ied}{jr}@SPILL@ SPU_RET(ctx);"
            return (f"{_ied}ctx->pc = spu_pref_word({g(tgt_reg)}); {self._jump('ctx->pc')}"
                    f"@SPILL@ g_spu_trampoline_fn = spu_indirect_branch; return;")
        if mn == "iret":
            return (f"{_ied}ctx->pc = ctx->srr0; "
                    "@SPILL@ g_spu_trampoline_fn = spu_indirect_branch; return;")
        if mn in ("bisl",):
            link_rt = insn.raw & 0x7F
            tgt_reg = _reg(ops[-1])
            rs, rr = ("const int32_t _rd = ctx->reloc_delta; ", " ctx->reloc_delta = _rd;") if self.reloc else ("", "")
            return (f"{{ uint32_t _tg = spu_pref_word({g(tgt_reg)}); {g(link_rt)} = spu_link({self._pc((addr + 4) & 0x3FFFC)}); "
                    f"int32_t _si = (int32_t)ctx->image_id; {rs}"
                    f"{_ied}ctx->pc = _tg; @SPILL@ ctx->host_depth++; "
                    f"SPU_ICALL(ctx); spu_call_return(ctx, {self._pc(addr + 4)}); "
                    f"ctx->host_depth--; ctx->image_id = _si;{rr} @RELOAD@ }}")
        if mn in ("bisled",):
            link_rt = insn.raw & 0x7F
            tgt_reg = (insn.raw >> 7) & 0x7F
            return (f"{{ uint32_t _tg = spu_pref_word({g(tgt_reg)}); {g(link_rt)} = spu_link({self._pc((addr + 4) & 0x3FFFC)}); "
                    f"if ((ctx->event_status & ctx->event_mask) != 0) {{ "
                    f"{_ied}ctx->pc = _tg; "
                    f"@SPILL@ g_spu_trampoline_fn = spu_indirect_branch; return; }} }}")
        if mn in ("biz", "binz", "bihz", "bihnz"):
            cond = self._cond(mn[1:], _reg(ops[0]))
            tgt_reg = _reg(ops[1])
            if (tgt_reg == "0" and addr not in self.bi_r0_jump) \
                    or addr in self.link_return:
                jr = self._jump(f"spu_pref_word({g(tgt_reg)})", True)
                if tgt_reg != "0":
                    return f"if ({cond}) {{ {_ied}{jr}@SPILL@ SPU_RET_REG(ctx, {tgt_reg}); }}"
                return f"if ({cond}) {{ {_ied}{jr}@SPILL@ SPU_RET(ctx); }}"
            return (f"if ({cond}) {{ {_ied}ctx->pc = spu_pref_word({g(tgt_reg)}); {self._jump('ctx->pc')}"
                    f"@SPILL@ g_spu_trampoline_fn = spu_indirect_branch; return; }}")

        if mn in ("hbr", "hbra", "hbrr"):
            return "/* branch hint (ignored) */;"
        if mn == "mtspr":
            return "/* mtspr: SPR write ignored */;"

        self.unsupported[mn] = self.unsupported.get(mn, 0) + 1
        return (f'/* TODO spu: {mn} {insn.operands} */ '
                f'@SPILL@ spu_unsupported(0x{insn.addr:X}, "{mn}"); @RELOAD@')

    def _cond(self, mn: str, reg: str) -> str:
        word = f"spu_pref_word({self._g(reg)})"
        half = f"(uint16_t){word}"
        table = {
            "brz": f"{word} == 0",      "brnz": f"{word} != 0",
            "brhz": f"{half} == 0",     "brhnz": f"{half} != 0",
            "iz": f"{word} == 0",       "inz": f"{word} != 0",
            "ihz": f"{half} == 0",      "ihnz": f"{half} != 0",
        }
        return table.get(mn, f"{word} != 0")

    def _uncond_branch(self, tgt, func: LiftedFunction) -> str:
        if tgt is None:
            return "/* TODO spu: unresolved branch */;"
        if func.start_addr <= tgt < func.end_addr:
            return f"goto loc_{tgt:08X};"
        self.branch_targets.add(tgt)
        return (f"{{ @SPILL@ SPU_DIRECT(ctx, {self._pc(tgt)}, {self.prefix}spu_func_{tgt:08X}); }}")

    def emit_header(self) -> str:
        lines = [HEADER_PREAMBLE, ""]
        for f in self.functions:
            lines.append(f"void {f.name}(spu_context* ctx);")
        defined = {f.start_addr for f in self.functions}
        for t in sorted(self.call_targets | self.branch_targets):
            if t not in defined:
                lines.append(f"void {self.prefix}spu_func_{t:08X}(spu_context* ctx); /* external */")
        lines.append("")
        lines.append("/* Runtime glue (runtime/spu/spu_channels.c) */")
        lines.append("void spu_register_function(uint32_t addr, void (*fn)(spu_context*));")
        lines.append("/* Call once at init to register this image's functions for")
        lines.append(" * indirect-branch dispatch (spu_indirect_branch). */")
        lines.append(f"void {self.prefix}spu_recomp_register(void);")
        lines.append("")
        return "\n".join(lines)

    def emit_source(self,header_name: str) -> str:
        lines = [SOURCE_PREAMBLE.format(header_name=header_name), ""]
        for f in self.functions:
            lines.append(f"void {f.name}(spu_context* ctx) {{")
            for b in f.body_lines:
                lines.append(b if b.endswith(":") else f"    {b}")
            lines.append("}")
            lines.append("")

        defined = {f.start_addr for f in self.functions}
        externs = sorted((self.call_targets | self.branch_targets) - defined)
        if externs:
            lines.append("/* Indirect-dispatch stubs for cross-function targets the")
            lines.append(" * function detector did not seed (typically conditional")
            lines.append(" * branches that escape a function's range). */")
            for t in externs:
                lines.append(f"void {self.prefix}spu_func_{t:08X}(spu_context* ctx) {{")
                pc = self._pc(t) if self.reloc else f"0x{t:X}u"
                lines.append(f"    ctx->pc = {pc}; "
                             f"g_spu_trampoline_fn = spu_indirect_branch; return;")
                lines.append("}")
            lines.append("")

        lines.append("/* Function table */")
        lines.append("typedef struct { uint32_t addr; void (*func)(spu_context*); const char* name; } spu_func_entry;")
        lines.append("static const spu_func_entry spu_function_table[] = {")
        for f in self.functions:
            lines.append(f'    {{ 0x{f.start_addr:08X}u, {f.name}, "{f.name}" }},')
        lines.append("    { 0, NULL, NULL }")
        lines.append("};")
        lines.append("")
        lines.append(f"void {self.prefix}spu_recomp_register(void) {{")
        lines.append("    for (const spu_func_entry* e = spu_function_table; e->func; ++e)")
        lines.append("        spu_register_function(e->addr, e->func);")
        lines.append("}")
        lines.append("")
        return "\n".join(lines)


def main() -> None:
    p = argparse.ArgumentParser(description="SPU to C lifter for ps3recomp")
    p.add_argument("input", nargs="?", default=None,
                   help="Raw SPU binary (local-store image) or segment. "
                        "Omit if --auto-functions is set.")
    p.add_argument("--output", "-o", default=".", help="Output directory")
    p.add_argument("--header-name", default="spu_recomp.h")
    p.add_argument("--source-name", default="spu_recomp.c")
    p.add_argument("--base", type=lambda x: int(x, 0), default=0,
                   help="Base local-store address")
    p.add_argument("--offset", type=lambda x: int(x, 0), default=0)
    p.add_argument("--length", type=lambda x: int(x, 0), default=0)
    p.add_argument("--functions", metavar="FILE",
                   help="JSON list [{\"start\":addr,\"end\":addr}, ...]")
    p.add_argument("--auto-functions", metavar="ELF",
                   help="Auto-detect function boundaries from the given SPU "
                        "ELF using find_spu_functions.py (entry + brsl/brasl "
                        "targets + STT_FUNC symbols). When set, .text is "
                        "read from this ELF and the positional <input> arg "
                        "is ignored.")
    p.add_argument("--report", help="Write machine-readable generation diagnostics JSON")
    p.add_argument("--trace", action="store_true",
                   help="Emit spu_trace_pc/spu_trace_rt around each instruction "
                        "for §3 diff-vs-RPCS3 validation. Output goes to stderr "
                        "unless spu_trace_init(path) is called by the harness.")
    p.add_argument("--symbol-prefix", default="",
                   help="Prefix for all emitted spu_func_* / spu_recomp_register "
                        "symbols, so multiple lifted SPU images can link into one "
                        "binary without colliding (e.g. flow_spu_00_). Default: none.")
    p.add_argument("--extra-funcs", default="",
                   help="Comma-separated extra function entry addresses (e.g. "
                        "0x10F8,0x808) to add as boundaries -- for indirect-branch "
                        "targets that --auto-functions can't detect statically. "
                        "Splits the containing auto-detected function at each addr.")
    p.add_argument("--return-entries", action="store_true",
                   help="Also make the return address of every call (brsl, "
                        "brasl, bisl, bisled) an entry point. Code that is "
                        "resumed rather than returned to needs it: a SPURS task "
                        "calls the policy module's syscall entry, the policy "
                        "saves the task and exits to the kernel (abandoning the "
                        "host frames), and later resumes the task by branching "
                        "to that return address. Splits existing functions only "
                        "(never seeds a gap), and the splits do not start new "
                        "--merge-chunks groups, so straight-line speed is kept.")
    p.add_argument("--code-end", type=lambda x: int(x, 0), default=0,
                   help="Address where executable code ends and an embedded "
                        "rodata/const tail begins. Drops any auto-detected "
                        "function starting at/after this address and caps any "
                        "function's end here, so the data tail is left "
                        "un-disassembled. For images with a large data tail in "
                        ".text whose bytes decode as in-range branches and seed "
                        "garbage `functions` (e.g. the LBP WWS physics jobmods, "
                        "which append a zlib inflate string table + float tables "
                        "after the code at 0xAE68 / 0xAE48).")
    p.add_argument("--merge-chunks", action="store_true",
                   help="Emit each run of contiguous chunks from one call target "
                        "to the next as ONE C function (branches between them "
                        "become gotos) instead of one function per chunk linked "
                        "by trampolines. Every chunk is still emitted and "
                        "registered on its own for indirect entry, so this only "
                        "changes speed, not which code can be reached.")
    p.add_argument("--reloc", action="store_true",
                   help="Position-independent code the title places at a different LS "
                        "address per load: lift once at --base, and offset every "
                        "pc-derived address by ctx->reloc_delta at run time (register "
                        "with spu_overlay_register_region_reloc).")
    p.add_argument("--no-promote", action="store_true",
                   help="Keep every SPU register access in ctx->gpr instead of function locals "
                        "(reference lifting for the register-promotion differential test).")
    args = p.parse_args()

    if args.auto_functions:
        from find_spu_functions import detect_functions, infer_code_end, parse_elf, pick_text, text_image
        with open(args.auto_functions, "rb") as f:
            elf_buf = f.read()
        funcs, (text_off, base, size) = detect_functions(elf_buf)
        if not args.code_end:
            inferred = infer_code_end(elf_buf)
            if inferred:
                args.code_end = inferred
                sys.stderr.write("[spu_lifter] no executable sections: code ends at 0x%X, "
                                 "the first undecodable word follows and nothing in the code "
                                 "references past it\n" % inferred)
        data, _ = text_image(elf_buf, parse_elf(elf_buf)["phs"])
        if args.base != 0:
            base = args.base
        bounds = funcs
    else:
        with open(args.input, "rb") as f:
            data = f.read()
        if data[:4] == b"ELF" and args.offset == 0 and args.base == 0:
            p.error("input is an ELF but no --auto-functions/--offset/--base was "
                    "given: it would be lifted as a raw image at base 0, placing "
                    "every function at its FILE OFFSET instead of its local-store "
                    "address. Pass --auto-functions <same elf> to lift it as an "
                    "ELF, or --offset/--base to confirm a raw read.")
        data = data[args.offset:]
        if args.length:
            data = data[:args.length]
        base = args.base

        if args.functions:
            with open(args.functions) as f:
                flist = json.load(f)
            bounds = [(int(str(e["start"]), 0), int(str(e["end"]), 0))
                      for e in flist]
        else:
            bounds = [(base, base + len(data))]

    if args.return_entries:
        hi = args.code_end or (base + len(data))
        rets = sorted({i.addr + 4 for i in disassemble_spu(data, base)
                       if i.mnemonic in ("brsl", "brasl", "bisl", "bisled")
                       and i.addr + 4 < hi})
        newb = []
        for (s0, e0) in sorted(set(bounds)):
            cuts = [a for a in rets if s0 < a < e0]
            prev = s0
            for a in cuts:
                newb.append((prev, a)); prev = a
            newb.append((prev, e0))
        by_start = {}
        for s0, e0 in newb:
            if s0 not in by_start or e0 < by_start[s0]:
                by_start[s0] = e0
        sys.stderr.write("[spu_lifter] return entries: %d call return address(es), %d -> %d bound(s)\n"
                         % (len(rets), len(bounds), len(by_start)))
        bounds = sorted(by_start.items())

    if args.extra_funcs:
        extra = [int(x, 0) for x in args.extra_funcs.split(",") if x.strip()]
        bset = sorted(set(bounds))
        for a in extra:
            newb = []
            split = False
            for (s, e) in bset:
                if s < a < e:
                    newb.append((s, a)); newb.append((a, e)); split = True
                else:
                    newb.append((s, e))
            if not split and not any(s == a for s, _ in bset):
                nxt = min([s for s, _ in bset if s > a] + [base + len(data)])
                newb.append((a, nxt))

            bset = sorted(set(newb))
        by_start = {}
        for s, e in bset:
            if s not in by_start or e < by_start[s]:
                by_start[s] = e
        bounds = sorted(by_start.items())
        sys.stderr.write("[spu_lifter] added extra funcs: %s\n" %
                         ", ".join("0x%X" % a for a in extra))

    if args.code_end:
        ce = args.code_end
        before = len(bounds)
        bounds = [(s, min(e, ce)) for (s, e) in bounds if s < ce]
        sys.stderr.write("[spu_lifter] code-end 0x%X: kept %d/%d bound(s), "
                         "data tail left un-disassembled\n"
                         % (ce, len(bounds), before))

    insns = disassemble_spu(data, base)

    lifter = SPULifter(trace=args.trace, prefix=args.symbol_prefix)
    lifter.reloc = args.reloc
    lifter.promote = not args.no_promote
    lifter.defer = True
    lifter.bi_r0_jump = compute_bi_r0_jumps(insns, bounds)
    if lifter.bi_r0_jump:
        print(f"  {len(lifter.bi_r0_jump)} `bi $r0` computed-jump site(s) "
              f"(r0 set by lqa/lqr/il/ila, not a link): "
              f"{', '.join(f'0x{a:X}' for a in sorted(lifter.bi_r0_jump))}")
    lifter.link_return = compute_link_returns(insns, bounds)
    if lifter.link_return:
        print(f"  {len(lifter.link_return)} non-r0 link-register return site(s) "
              f"(`bi $rN` where rN is a brsl/bisl link reg): "
              f"{', '.join(f'0x{a:X}' for a in sorted(lifter.link_return))}")
    lifter.func_starts = {s for s, e in bounds}
    groups = {}
    if args.merge_chunks:
        seeds = {base}
        if args.extra_funcs:
            seeds |= {int(x, 0) for x in args.extra_funcs.split(",") if x.strip()}
        groups = merge_chunk_groups(insns, bounds, 4000, entry_points=seeds)
        print(f"  {len(groups)} merged function group(s) "
              f"(--merge-chunks, max 4000 insns)")
    for s, e in bounds:
        lifter.lift_function(insns, s, groups.get(s, e))
    lifter.finalize()

    os.makedirs(args.output, exist_ok=True)
    hp = os.path.join(args.output, args.header_name)
    sp = os.path.join(args.output, args.source_name)
    with open(hp, "w") as f:
        f.write(lifter.emit_header())
    with open(sp, "w") as f:
        f.write(lifter.emit_source(args.header_name))

    if args.report:
        with open(args.report, "w", encoding="utf-8") as report:
            json.dump({"functions": [[f.start_addr, f.end_addr] for f in lifter.functions],
                       "unsupported": lifter.unsupported,
                       "call_targets": sorted(lifter.call_targets),
                       "branch_targets": sorted(lifter.branch_targets)}, report, indent=2)

    print(f"Wrote {hp}")
    print(f"Wrote {sp}")
    print(f"  {len(lifter.functions)} function(s) lifted")
    print(f"  {len(lifter.call_targets)} call target(s)")
    if lifter.unsupported:
        total = sum(lifter.unsupported.values())
        print(f"  {total} unsupported instruction(s) across "
              f"{len(lifter.unsupported)} mnemonic(s):")
        for mn, n in sorted(lifter.unsupported.items(), key=lambda kv: -kv[1]):
            print(f"      {mn:<10s} {n}")


if __name__ == "__main__":
    main()
